internal object DuaBrxDraft8 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_eid_takbeer" to DuaText("ईदनि लामायाव तकबीर", "अल्लाहआ देरसिन, अल्लाहआ देरसिन, अल्लाहनि अनगा रावबो इसोर गैया, आरो अल्लाहआ देरसिन, अल्लाहआ देरसिन, आरो गासिबो बाख्नायनाया अल्लाहनि थाखाय।", "अखाफोर नुजानायनि हरनिफ्राय ईद अल-फितरनि आरजसिम, जरखायै ईद फोथारनि लामायाव।", "कुराननि बिथोनः'जाहाथे नों साननायखौ फोजोब आरो अल्लाहनि गेदेमाथिखौ फोसावदोंमोन'(अल-बकाराह 2:185)। इब्न मसूद (रा) आ बे तकबीरखौ बुंदोंमोन।"),
        "dua_ahsin_aqibatana" to DuaText("गासैबो बिथिङाव जोंनि जोबनायखौ मोजां खालाम।", "ऐ अल्लाह, गासैबो बिथिङाव जोंनि जोबनायखौ मोजां खालाम आरो जोंफोरखौ बे मुलुगाव लाजि आरो जोबनायाव साजानिफ्राय रैखा खालाम।", "मोनफ्रोमबो बिथिङाव मोजां फिथायनि थाखाय।", "जाय बे दुआखौ खालामो आरो बिजिरनायनि सिगां थैयो (बिजिरनायनिफ्राय रैखा)।"),
        "dua_fadlika_wa_rahmatik" to DuaText("आं नोंनि अनथोब आरो अननायखौ सोङो।", "ऐ अल्लाह, आं नोंखौ नोंनि अनथोब आरो नोंनि अननायनि थाखाय सोङो, मानोना नोंनि अनगा रावबो बेनि बिगोमा नङा।", "जेब्ला राहा आरो अननायनि थाखाय सोङो।", "आलासिफोरा पैगंबर सल्लल्लाहु अलैहि वस्लमनि खाथियाव फैदोंमोन जेब्ला जाग्रा आदार गैयामोन; बिथाङा बे दुआखौ बानायदोंमोन, आरो बेनि उनाव मोनसे अनथोब फैदोंमोन।"),
        "dua_allahu_akbar_kabira_2696" to DuaText("सासे बेदुइननो फोरोंनाय सोदोबफोर", "अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे। अल्लाहआ बयनिख्रुइबो देरसिन, गोबां बाखनायनाय, अल्लाहनि थाखाय गोबां; महिमाआ मुलुगनि इसोर, आरो अल्लाहनि अनगा जेबो गोहो एबा गोहो गैया, सोर गोहोगोरा, गियानगोनां।", "मोनसे बेदुइननो फोरोंनाय-धिकर आरो दुआनि मोनसे गुवार बाथ्रा।", "बिनि उनाव बिथांखौ'अल्लाहुम्माघफिर ली वारहामनी वाहदिनी वारजुकनी'बुंनो फोरोंनाय जादोंमोन।"),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("आं सिगाङाव आरो उनाव जायखौ हरदोंमोन बिखौ क्षमा खालाम।", "ऐ अल्लाह, आं सिगाङाव आरो उनाव जाय पापफोर खालामदोंमोन, आं जायखौ गोथों खालामदोंमोन आरो जायखौ खुलाङै खालामदोंमोन, आंनि बांद्राय खालामनायफोर आरो जायखौ नों आंनिख्रुइ साबसिन मोनथियो, बेखौ आंखौ बावगार। नोंनो सिगां लाबोयो आरो जायखौ फिन हरहोयो; नोंनि अनगायै रावबो इसोर गैया।", "ताशाहहुद आरो सालावतनि उनाव, सालामनि सिगां।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा आरज गाबनायनि जोबनायाव ताशाहहुद आरो सालामनि गेजेराव बेखौ फरायदोंमोन।"),
        "dua_jiddi_wa_hazli" to DuaText("आंनि गोरोनथि आरो आंनि जिंगाखौ बावगार।", "ऐ अल्लाह, आं गोरोनथिङै आरो मिनिथावै, गोरोन्थिजों आरो सानथांखिजों खालाम जानाय पापफोरखौ आंखौ बावगार-आरो बे गासैबो आंनि सिङाव दं।", "मिथिजानाय आरो मिथिजायै गासैबो रोखोमनि पापनि थाखाय क्षमा।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनि मोनसे गुवार इस्तिघफार।"),
        "dua_rising_ruku_mil" to DuaText("रुकुनि उनाव-सोरगोखौ आबुं खालाम।", "जोंनि इसोर, गासिबो बाख्नायनाया नोंनिनो, सोरगोखौ आबुं खालामनाय, बुहुमखौ आबुं खालामनाय आरो बिनि उनाव नोंथाङा जाय नांगौ बेखौ आबुं खालामनाय।", "रुकुनिफ्राय ओंखारनायनि उनाव,'रब्बाना लकल-हमद'जों लोगोसे।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा रुकुनिफ्राय ओंखारनायाव बे बाथ्रा बुंदोंमोन।"),
        "dua_istiftah_kabira" to DuaText("अल्लाहआ बयनिख्रुइ देरसिन, गोबां बाख्नायजानाय।", "अल्लाहआ बयनिख्रुइबो देरसिन, गोबां; गोबां बाख्नायनाया अल्लाहनि थाखाय; आरो अल्लाहा फुं-बेलासियाव गोग्गानाय।", "जेब्ला आरजखौ जागायो (जागायजेन्नाय बाख्नायनायनि मोनसे महर)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बुङोः बिनि थाखाय सोरगोनि दरजाखौ खेवनाय जादोंमोन।"),
        "dua_q_ashku_bathhi" to DuaText("याकूब (अ. स.) नि दुआ-आं खालि अल्लाहनो खोन्थारो।", "आं आंनि दुखु आरो दुखुखौ खालि अल्लाहनो खोन्थाबो।", "गोथौ दुखु आरो जुदा-आलादा।", "याकूब (ए. एस.) आ इउसुफ (ए. एस.) निफ्राय गाव गाव गाव आलादा जानाय समाव बे बाथ्राखौ बुंदोंमोन।"),
        "dua_q_khayrun_hafiza" to DuaText("अल्लाहआ साबसिन रैखाथि होग्रा।", "अल्लाहआ साबसिन रैखाथि होग्रा आरो बियो अनजाथावनि गेजेराव बांसिन अनजाथाव।", "जेब्ला गथ'साफोर एबा मोजां मोनग्राफोरनि दावबायनायाव दैथायहरो।", "याकूब (आ. स.) आ गावनि फिसाज्लाखौ अल्लाहनो बावनाय समाव बे बाथ्रा बुंदोंमोन।"),
        "dua_q_aqraba_rashada" to DuaText("आंनि इसोरआ आंनो आगदाथिंनि खाथिथाराव लामा दिन्थिहो।", "जानो हागौ आंनि इसोरआ आंखौ बैसिम लामा दिन्थिगोन जाय मोजां आखुथायनि बिनि बांसिन खाथि।", "जेब्ला माबा मोनसे बिथिङाव साबसिन लामा नागिरो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमखौ बावगारनो उनाव बे बाथ्राखौ बुंनो बुंनाय जादोंमोन।"),
        "dua_q_sawa_as_sabil" to DuaText("मुसा (ए. एस.) नि दुआआ-आंखौ थि लामायाव दैदेन।", "जानो हागौ आंनि इसोरआ आंखौ थि लामायाव दैदेनगोन।", "जेब्ला गोदान दावबायनायाव एबा मोनसे मिथिजायै लामायाव ओंखारो।", "मुसाया (एएस) बे बाथ्राखौ अब्ला बुंदोंमोन जेब्ला बियो माद्यान फारसे गिदिंदोंमोन।"),
        "dua_q_not_among_wrongdoers" to DuaText("आंखौ गोरोन्थि खालामग्राफोरनि गेजेराव दोन।", "आंनि इसोर, आंखौ गोरोनथि खालामग्रा सुबुंफोरनि गेजेराव दोन।", "मोनसे दुआआ अल्लाहखौ सासेखौ गोरोन्थि खालामग्राफोरनिफ्राय आलादा दोननो थाखाय बुङो।", "मोनसे दुआआ अल्लाहखौ सासेखौ गोरोन्थि खालामग्राफोरनिफ्राय आलादा दोननो थाखाय बुङो।"),
        "dua_q_do_not_make_us_trial" to DuaText("जोंखौ मोनसे आनजाद खालामहो।", "ऐ जोंनि इसोर, फोथायनो हायैफोरनि थाखाय नोंखौ आनजाद खालामहो आरो जोंनि इसोर, नोंखौ क्षमा खालाम। थारैनो, नोंनो गोहोगोरा, गियानगोनां।", "इब्राहिम (ए. एस.) आरो बिथांनि लोगोफोरनि दुआ।", "इब्राहिम (ए. एस.) आरो बिथांनि लोगोफोरनि दुआ।"),
        "dua_morning_witness" to DuaText("तावहिदनि थाखाय फुंनि साखि।", "ऐ अल्लाह, आं फुंआव हाबदोंमोन, नोंनो, नोंनि राजउलाफादनि बाहागिरिया, नोंनि फारसिफोर आरो नोंनि गासै सोरजिलुफोरखौ लिंहरनानै बे बाथ्राखौ साखि होनो थाखाय दि नोंनो अल्लाह, नोंनि अनगा रावबो इसोर गैया, सोलायै, बाहागोआरि गैयालासे, आरो मुहम्मदआ नोंनि बान्दा आरो रसूला।", "बुंफुरलुआव बेखौ फुंनि ब्रै खेब बुंनायनि मुंख'नाय दं।", "बुंफुरलुआव बेखौ फुंनि ब्रै खेब बुंनायनि मुंख'नाय दं।"),
        "dua_evening_witness" to DuaText("तौहिदनो बेलासनि साखि।", "ऐ अल्लाह, आं बेलासियाव हाबदोंमोन, नोंनो, नोंनि राजउलाफादनि बाहागिरिया, नोंनि फारसिफोर आरो नोंनि गासै सोरजिलुफोरखौ लिंहरनानै बे बाथ्राखौ साखि होनो थाखाय दि नोंनो अल्लाह, नोंनि अनगा रावबो इसोर गैया, सोलायै, बाहागोआरि गैयालासे, आरो मुहम्मदआ नोंनि बान्दा आरो रसूला।", "बुंफुरलुआव बेखौ बेलासियाव खनब्रै बुंनायनि मुंख'नाय दं।", "बुंफुरलुआव बेखौ बेलासियाव खनब्रै बुंनायनि मुंख'नाय दं।"),
        "dua_morning_blessing" to DuaText("बोर होनायनि थाखाय फुंनि थाखाय थैंकस।", "ऐ अल्लाह, दिनै फुंआव आं एबा नोंनि सोरजिनाया जाय बोर मोनदों, बेयो नोंनिफ्रायल ', बाहागोआरि गैयालासे; बेनिखायनो गासिबो बाख्नायनायनाय आरो गासिबो बाखनायनाय नोंनो।", "अल्लाहनि बोरनि थाखाय बाखनायनायनि फुंनि दिकर।", "अल्लाहनि बोरनि थाखाय बाखनायनायनि फुंनि दिकर।"),
        "dua_evening_blessing" to DuaText("बोर होनायनि थाखाय बेलासनि थाखाय थैंकस।", "ऐ अल्लाह, दिनै बेलासियाव आं एबा नोंनि सोरजिनाया जाय बोर मोनदों, बेयो नोंनिफ्रायल ', बाहागोआरि गैयालासे; बेनिखायनो गासिबो बाख्नायनायनाय आरो गासिबो बाखनायनाय नोंनो।", "अल्लाहनि बोरनि थाखाय सायुङाव बाखनायनाय।", "अल्लाहनि बोरनि थाखाय सायुङाव बाखनायनाय।"),
    )
}
